function decisionEvent(){if(!state.accepted)return '';return `<div class="event"><span class="event-mark">${icon('check','green')}</span><div>你记录了本轮页面范围决定<p>${choiceLabel()}。目标仍有待体验项。</p>${state.decisionRecord?.note?`<p>补充说明：${esc(state.decisionRecord.note)}</p>`:''}</div><time>${state.decisionRecord?.at?new Date(state.decisionRecord.at).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):'已记录'}</time></div>`}
