const ib=(name,label,action)=>`<button class="icon-btn" aria-label="${label}" title="${label}" data-action="${action}">${icon(name)}</button>`;
function preview(){return `<div class="website-preview" aria-label="Molis AI 网站设计样例"><div class="mini-nav"><strong>molis ai</strong><span>社区</span><span>观点</span><span>一起探索</span></div><h3>把好奇心，<br>变成一起做的事。</h3><p>一个由创造者共同建设的 AI 社区。<br>从一个问题开始，做出真实的改变。</p><span class="mini-btn">认识 Molis AI</span><div class="preview-art" aria-hidden="true"><i></i><i></i><i></i></div><span class="preview-caption">首页方向稿 / v3</span></div>`}
