function home(){const f=flow.getStatus();const reviewNow=f.needsReview&&!f.draftDirty&&!f.needsRevision;return `<div class="page home-page"><div class="home-title"><div><h1>接着，把事情做好。</h1><p>${esc(f.summary)}</p></div><span class="date-type">9 月 21 日 / 周一</span></div><div class="resume-feature"><div class="resume-copy"><div class="flex brown">${icon('note')}<small>接着上次的文稿</small></div><h2>社区加入指引</h2><p>${f.needsRevision?'这版收到一条具体修改意见。回到原文，连同反馈一起继续。':reviewNow?'你提交的新版本已回到目标，接下来核对本版与原要求。':f.adopted?'新的加入方式已采用。可以带着依据，修订当前文稿。':'上次写到“第一次参与”。当前草稿已保留，阅读位置也还在。'}</p>${btn(reviewNow?'检查这一版':'继续写这篇',reviewNow?'flow-open-review':'flow-open-writing','primary','arrow')}<button class="btn link small" data-goal="design">查看目标</button></div><div class="resume-manuscript"><div class="small muted">PAGES / 工作草稿</div><h3>第一次参与<br>Molis AI</h3><div class="manuscript-lines"><i></i><i></i><i></i></div><div class="small muted">${f.hasResult?'已交回 v'+f.version:'尚未交回成果'} · 私人草稿保留</div></div></div>${flow.homeNotice()}<div class="section-head"><h2>现在能推进什么</h2><button class="btn link small" data-page="inbox">待你决定 ${icon('chevron-right')}</button></div>${!state.accepted?`<button class="attention-row" data-decision="scope">${icon('circle-alert','amber')}<div class="row-copy">确认首轮页面范围<p>决定后，首页实现可以据此继续。</p></div><div class="row-tail">${badge('需要取舍','warn')}${icon('chevron-right')}</div></button>`:`<button class="attention-row" data-goal="build">${icon('code','cyan')}<div class="row-copy">继续首页与内容导航<p>${esc(choiceLabel())}；页面范围决定已记录。</p></div><div class="row-tail">${badge('可继续','progress')}${icon('chevron-right')}</div></button>`}<button class="attention-row" data-action="${reviewNow?'flow-open-review':'flow-open-writing'}">${icon(reviewNow?'review':'note',reviewNow?'rose':'brown')}<div class="row-copy">${reviewNow?'审阅刚交回的加入指引':'修订社区加入指引'}<p>${f.needsRevision?'反馈已经定位到具体段落。':f.adopted?'本轮加入方式已确认，依据会跟着文稿。':'可以继续原草稿；新的反馈仍待你取舍。'}</p></div><div class="row-tail">${badge(reviewNow?'待审阅':'可继续',reviewNow?'warn':'progress')}${icon('chevron-right')}</div></button><details class="quiet-updates"><summary>安静的变化与等待项<span class="small muted">1 条新材料 · 1 项等待</span></summary><button class="recent-item" data-action="first-feed">${icon('rss','brown')}一条新的设计观察<span class="spacer"></span>${icon('chevron-right')}</button><div class="recent-item">${icon('clock','slate')}手机加入路径体验<span class="spacer"></span><small class="muted">等待可运行的网站</small></div></details><div class="section-head"><h2>工作留下的成果</h2><button class="btn link small" data-page="artifacts">查看全部</button></div>${flow.resultSummary()}<div class="recent-grid"><button class="recent-item" data-action="preview">${icon('image','rose')}<div>首页方向稿<small>v3 / ${f.adopted?'加入区域待按新要求复核':'按当前约定制作'}</small></div><span class="spacer"></span>${icon('chevron-right')}</button><button class="recent-item" data-action="research-doc">${icon('book','slate')}<div>设计参考<small>v2 / 保留引用版本</small></div><span class="spacer"></span>${icon('chevron-right')}</button></div></div>`}
function requirements(){return `<div class="requirement">${icon('completed','green')}<div class="req-copy">保留五类内容入口<p>导航草案已覆盖；方向稿 v3 可查看。</p></div>${badge('已有依据','good')}</div><div class="requirement">${icon(flow.getStatus().adopted?'circle-alert':'completed',flow.getStatus().adopted?'amber':'green')}<div class="req-copy">${flow.getStatus().adopted?'可以直接报名参加一次活动':'能看懂社区做什么、如何参与'}<p>${flow.getStatus().adopted?'要求已更新；方向稿 v3 仍按旧加入方式，需要复核。':'首页文案与入口已形成方向稿。'}</p></div>${badge(flow.getStatus().adopted?'需要复核':'已有依据',flow.getStatus().adopted?'warn':'good')}</div><div class="requirement">${icon('circle-alert','amber')}<div class="req-copy">手机上可以完成加入路径<p>尚无真人体验记录；不能据设计稿判定通过。</p></div>${badge('待体验','warn')}</div>`}
function notes(){return `${decisionEvent()}${state.notes.map(n=>`<div class="event"><span class="event-mark">${icon('user')}</span><div>你记录了一条备注<p>${esc(n)}</p></div><time>刚刚</time></div>`).join('')}<div class="event"><span class="event-mark">${icon('output','rose')}</span><div>首页方向稿更新到 v3<p>基于设计参考 v2，保留五类内容入口。</p></div><time>10:24</time></div><div class="event"><span class="event-mark">${icon('terminal','purple')}</span><div>Codex 留下了实现说明<p>建议先确认导航范围，再进入页面实现。</p></div><time>09:48</time></div>`}
function composer(){return `<div class="note-composer"><textarea aria-label="工作备注" placeholder="记下一个进展、问题或下一步…" data-draft>${esc(state.note)}</textarea><div class="spread"><span class="small">备注不改变目标约定</span>${btn('记一笔','save-note','secondary','plus')}</div></div>`}
function goal(){const g=currentGoal();if(g.id!=='design')return otherGoal(g);if(state.mode==='atlas')return atlas(true);return `<div class="detail-header"><div class="crumb"><button data-page="goals">目标</button>${icon('chevron-right')}<span>让新成员更快理解 Molis AI</span></div><div class="spread"><div class="flex">${badge(state.accepted?'方向已记录':'待你确认',state.accepted?'good':'warn',state.accepted?'check':'circle-alert')}<span class="small muted">设计 / 本地示例</span></div>${btn('当前约定','agreement','','review')}</div><h1>网站首页视觉更新</h1><p>让第一次访问的人看懂社区在做什么，并找到适合自己的参与方式。</p></div>${flow.goalNotice()}<div class="goal-layout"><div class="goal-main">${flow.resultSummary()}<div class="spread block-title"><span>当前成果</span><span class="small muted">09:24 更新</span></div>${artifact()}<div class="block-title requirements-head">${icon('review')}完成还需要什么<span class="spacer"></span><small class="muted">逐项判断，不折算进度</small></div>${requirements()}<div class="section-head"><h2>工作记录</h2>${btn('全部历史','history','','history')}</div>${notes()}${composer()}</div><aside class="goal-aside"><div class="side-block"><div class="block-title">${icon('inbox','green')}下一步</div><div class="decision-note">${state.accepted?'方向已记录，目标仍未完成':'首轮更新哪些页面？'}<p>${state.accepted?'下一步核对窄屏和真实加入路径。':'这个决定影响首页的导航结构与实现范围。'}</p>${btn(state.accepted?'查看待体验项':'查看取舍',state.accepted?'review-decision':'scope-decision','secondary','arrow')}</div></div><div class="side-block"><div class="block-title">${icon('link')}这轮工作的依据</div><button class="context-item" data-action="agreement">${icon('target')}<span>目标约定 v2<small>本轮使用的结果与边界</small></span></button><button class="context-item" data-action="research-doc">${icon('book')}<span>社区网站设计参考 v2<small>界面与工作流的交互观察</small></span></button><div class="context-item">${icon('lock')}<span>按指定版本引用<small>新版本出现时，不静默替换</small></span></div></div><div class="side-block"><div class="block-title">${icon('terminal')}继续工作</div><div class="people-row"><span class="avatar">C</span>Codex <small>上次使用</small></div><button class="nav-item settings-entry" data-page="sessions">打开关联会话<span class="spacer"></span>${icon('arrow')}</button><p class="small muted" style="line-height:1.8;margin-top:8px">查看会话不会自动执行。切换工具前先核对携带的上下文。</p></div></aside></div>`}
function journey(){return `<div class="journey" aria-label="目标接续路径">${[['research','研究依据','设计参考 v2','completed','done'],['design','设计方向','首页方向稿 v3','dot','active'],['build','页面实现','可继续已确认部分','code',''],['validation','真实验收','等待可运行版本','review','']].map(x=>`<button class="journey-step ${x[4]}" data-goal="${x[0]}"><span class="step-marker">${icon(x[3])}</span><h3>${x[1]}</h3><p>${x[2]}</p></button>`).join('')}</div>`}
function atlas(detail=false){return `<div class="atlas-home"><div class="atlas-heading spread"><div><div class="crumb">${icon('target','blue')}让新成员更快理解 Molis AI</div><h1>${detail?'网站首页视觉更新':'从依据，到真正可用。'}</h1><p>把这轮工作的输入、结果和待确认事项放在一起。</p></div><div class="draft-label">${icon('lock')}本地示例</div></div>${flow.goalNotice()}${flow.resultSummary()}<div class="comparison"><section class="compare-col"><h2>使用的依据 ${icon('input')}</h2><button class="input-paper" data-action="research-doc">${icon('book')}<div>社区网站<br class="desktop-br">设计参考</div><p>研究如何找回现场、处理变化、检查成果。</p>${badge('v2 · 当前引用')}</button><button class="context-item" data-action="agreement">${icon('target')}<span>目标约定 v2<small>内容范围、预期结果、验收</small></span></button><p class="small muted" style="line-height:1.8;margin-top:18px">下一轮换材料时，先看哪些工作会受影响。</p></section><section class="compare-col"><h2>本轮成果 ${badge('设计 / v3','progress')}</h2>${artifact()}<div class="relationship-strip">${icon('link')}引用 v2 ${icon('arrow')}方向稿 v3 ${icon('arrow')}<button data-goal="build">页面实现</button></div></section><section class="compare-col"><h2>人来确认 ${icon('review')}</h2><div class="check-line">${icon('completed','green')}<div>内容入口保留<p>五类入口已体现在草稿中</p></div></div><div class="check-line">${icon(state.accepted?'completed':'circle-alert',state.accepted?'green':'amber')}<div>首轮实现范围<p>${state.accepted?esc(choiceLabel()):'先更新首页与社区，还是一次更新全部页面？'}</p></div></div><div class="check-line">${icon('circle-alert','amber')}<div>手机上的加入路径<p>有设计，还没有真实体验依据</p></div></div><div style="margin-top:20px">${btn(state.accepted?'查看待体验项':'查看取舍',state.accepted?'review-decision':'scope-decision','primary','arrow')}</div><p class="small muted" style="margin-top:14px;line-height:1.8">${state.accepted?'决定已记录。仍需单独完成验收。':'只确认本轮范围，不代表认可最终结果。'}</p></section></div><div class="atlas-bottom"><section><div class="section-head"><h2>工作正在如何接续</h2>${btn('历史','history','','history')}</div>${notes()}</section><section><div class="section-head"><h2>给下一步留一句话</h2><span class="small muted">仅本地样例</span></div>${composer()}<div class="context-strip">${icon('link')}继续时带上：<span class="context-chip">当前目标</span><span class="context-chip">输入版本</span><span class="context-chip">尚未确认的事</span></div>${btn('核对接续上下文','handoff','','arrow')}</section></div></div>`}
function goalsPage(){let data=[...goals,...state.created].map(g=>g.id==='design'&&state.accepted?{...g,status:'方向已记录',kind:'good'}:g).filter(g=>(state.filter!=='attention'||g.kind==='warn')&&g.title.toLowerCase().includes(state.query.toLowerCase()));return `<div class="page"><div class="page-heading spread"><div><h1>目标</h1><p>先看要得到的结果，再看工作做到哪里。</p></div>${btn('新建目标','create','primary','plus')}</div><div class="toolbar"><div class="segmented" aria-label="目标视图"><button class="${state.listMode==='list'?'active':''}" data-listmode="list">${icon('list')}列表</button><button class="${state.listMode==='path'?'active':''}" data-listmode="path">${icon('tree')}接续</button></div><button class="btn ${state.filter==='attention'?'secondary':''}" data-action="filter-attention">${icon('filter')}${state.filter==='attention'?'仅待确认':'所有状态'}</button><span class="spacer"></span><label class="search-inline">${icon('search')}<input aria-label="搜索目标" placeholder="搜索目标" value="${esc(state.query)}" data-search-goals></label></div>${state.listMode==='path'?`<div class="readout">让新成员更快理解 Molis AI<p class="small muted">箭头表达结果的使用方向；执行顺序仍取决于已确认的依赖。</p></div>${journey()}`:''}<table class="goal-table"><thead><tr><th>目标与结果</th><th>当前状态</th><th>类型</th><th>最近更新</th></tr></thead><tbody><tr class="table-group"><td colspan="4">网站更新 <span class="count">${data.length}</span></td></tr>${data.map((g,i)=>`<tr><td><button data-goal="${g.id}">${icon(g.kind==='good'?'completed':g.kind==='warn'?'circle-alert':'circle',g.kind==='good'?'green':g.kind==='warn'?'amber':'blue')}<span>${esc(g.title)}</span></button></td><td>${badge(g.id==='design'&&state.accepted?'方向已记录':g.status,g.id==='design'&&state.accepted?'good':g.kind)}</td><td><span class="small muted">${g.type}</span></td><td><span class="small muted">${i<2?'今天':'昨天'}</span></td></tr>`).join('')}</tbody></table>${!data.length?`<div class="empty">${icon('search')}<h2>没有找到相关目标</h2><p>试试更短的关键词，或清除状态筛选。</p>${btn('清除筛选','clear-filter','secondary')}</div>`:''}<div class="continuity">${icon('info')}子目标完成数量不代替这个目标的验收。</div></div>`}
function otherGoal(g){return `<div class="page"><div class="crumb"><button data-page="goals">目标</button>${icon('chevron-right')}网站更新</div><div class="page-heading"><div class="flex">${badge(g.status,g.kind)}<span class="small muted">${g.type}</span></div><h1 style="margin-top:16px">${esc(g.title)}</h1><p>${esc(g.detail||'刚创建的本地演示目标')}</p></div><div class="readout">预期结果<p>${esc(g.outcome||({research:'整理可回溯的设计参考，让方向选择有具体依据。',build:'提供可实际使用的网站首页，保留已确认的内容入口。',writing:'让新成员知道加入后能做什么，以及从哪里开始。',validation:'用真实手机与首次访问场景走完认识社区到参与的路径。'}[g.id]||'补充你希望得到的结果。'))}</p></div><div class="section-head"><h2>关联工作</h2></div><button class="recent-item" data-goal="design">${icon('target','blue')}网站首页视觉更新<span class="spacer"></span>${icon('arrow')}</button><button class="recent-item" data-action="research-doc">${icon('book','slate')}设计参考 v2<span class="spacer"></span>${icon('arrow')}</button><div class="section-head"><h2>下一步</h2></div><p class="soft">${esc(g.detail||'先记录预期结果，再补充当前要求。')}</p><div style="margin-top:20px">${g.id==='build'?btn('查看关联会话','open-sessions','primary','terminal'):g.id==='research'?btn('打开研究资料','research-doc','primary','book'):g.id==='writing'?btn('继续编辑文稿','flow-open-writing','primary','note'):btn('回到首页设计','open-goal','secondary','back')}</div></div>`}
function feedDecision(){return `<h1>这条观察，要带进当前工作吗？</h1><p>${feeds[0][0]}</p><div class="readout">${feeds[0][3]}</div><div class="notice">进入原因：你从信息流手动加入。当前只保留原文引用，没有自动创建目标或改变约定。</div><div class="context-strip">${icon('link')}来源：设计观察 / 手工整理 ${state.material?badge('已存为资料','good'):badge('尚未存为资料')}</div>${state.feedInboxStatus==='open'?`<p>可以把这条观察留下作后续参考，也可以记录为已看过、不再需要处理。</p><div class="decision-footer">${btn('返回原文','first-feed','','back')}${btn('存为资料并处理','feed-keep','primary','bookmark')}${btn('标记已处理','feed-done','secondary','check')}</div>`:`<div class="notice">处理结果：${esc(state.feedInboxReceipt?.text||'已处理，原文保留。')}<p class="small">${state.feedInboxReceipt?.at?new Date(state.feedInboxReceipt.at).toLocaleString('zh-CN'):''}</p></div><div class="decision-footer">${btn('返回原文','first-feed','secondary','back')}${state.material?btn('查看已存资料','open-shelf','secondary','library'):''}${btn('重新打开','feed-reopen','','refresh')}</div>`}` }
function inbox(){const review=state.inboxId==='review',fromFeed=state.inboxId==='feed'&&state.feedInbox;return `<div class="decision-layout"><aside class="decision-list"><h2>需要你的判断 <span class="count">${attentionCount()}</span></h2>${!flow.getStatus().adopted&&!flow.getStatus().deferred?`<button class="decision-item" data-page="change">${badge('要求变化','warn')}<div>改成直接报名参加活动？</div><p>核对加入方式与受影响的成果</p></button>`:''}${flow.getStatus().needsReview?`<button class="decision-item" data-action="flow-open-review">${badge('新成果','warn')}<div>加入指引 v${flow.getStatus().version}</div><p>对照要求，检查这一版</p></button>`:''}<button class="decision-item ${state.inboxId==='scope'?'active':''}" data-decision="scope">${badge(state.accepted?'已记录':'页面范围决定',state.accepted?'good':'warn')}<div>首轮更新哪些页面？</div><p>首页视觉更新 / 会影响实现</p></button><div class="side-section">等待条件具备</div><button class="decision-item ${review?'active':''}" data-decision="review">${badge('待体验','warn')}<div>移动端加入路径</div><p>需要真人核对，尚不能收尾</p></button>${state.feedInbox?`<button class="decision-item ${fromFeed?'active':''}" data-decision="feed">${badge(state.feedInboxStatus==='open'?'来自信息流':'已处理',state.feedInboxStatus==='open'?'':'good')}<div>界面的上下文，应该让人看得见</div><p>${state.feedInboxStatus==='open'?'你手动加入，等待处理':'处理结果与原文都已保留'}</p></button>`:''}</aside><article class="decision-document"><div class="crumb">${fromFeed?`<button data-action="first-feed">${icon('rss','brown')}信息流原文</button>`:`<button data-goal="design">${icon('target','blue')}首页视觉更新</button>`}${icon('chevron-right')}待你决定</div>${fromFeed?feedDecision():review?`<h1>手机上，能顺利找到加入入口吗？</h1><p>方向稿已包含加入入口。但还没有人在实际手机上走完这条路径，当前无法把设计稿当作体验通过。</p><div class="section-head"><h2>需要亲自走过的路径</h2></div><div class="requirement">${icon('circle','amber')}第一次打开首页，理解社区正在做什么</div><div class="requirement">${icon('circle','amber')}找到加入入口，知道接下来会发生什么</div><div class="requirement">${icon('circle','amber')}完成加入，得到清晰反馈和返回入口</div><div class="notice">这是一份交互样例，没有可验收的生产网站。此项保持未验证。</div>${btn('查看方向稿','preview','secondary','image')}<div class="section-head"><h2>先记录一个观察</h2></div>${composer()}`:`<h1>首轮更新哪些页面？</h1><p>原范围包含产品、解决方案、观点、社区与 Molis Wikipedia。现在需要确认首轮实现方式，避免设计与开发使用不同的范围。</p><div class="notice">为什么现在要决定：下一轮会据此组织首页导航。选择会被记录，但不会自动启动开发或宣布目标完成。</div><div class="section-head"><h2>可选取舍</h2><button class="btn link small" data-action="agreement">查看当前约定</button></div><button class="option-row ${state.choice==='narrow'?'selected':''}" data-choice="narrow" aria-pressed="${state.choice==='narrow'}" ${state.accepted||state.pending?'disabled':''}><span class="option-radio"></span><div>保留五类入口，先完善首页与社区<p>信息架构保持完整；另外三类继续链接到现有内容，后续逐步更新。</p></div></button><button class="option-row ${state.choice==='full'?'selected':''}" data-choice="full" aria-pressed="${state.choice==='full'}" ${state.accepted||state.pending?'disabled':''}><span class="option-radio"></span><div>五类内容页一并更新<p>首轮覆盖更完整，需要增加内容整理、页面实现与逐页验收的投入。</p></div></button><div class="context-strip">${icon('link')}关联依据：<button class="context-chip" data-action="research-doc">设计参考 v2</button><button class="context-chip" data-action="preview">方向稿 v3</button></div>${state.accepted?`<div class="notice" style="border-color:var(--green);background:var(--green-soft);color:var(--green)">已记录本地样例决定：${esc(choiceLabel())}。目标仍有待体验项。${state.decisionRecord?.note?`<p>补充说明：${esc(state.decisionRecord.note)}</p>`:''}</div>${btn('回到工作面','open-goal','primary','back')}`:`<label class="small muted" for="decision-note">补充说明（可选）</label><textarea id="decision-note" class="field" style="margin-top:8px;min-height:76px" placeholder="给下一轮工作留下一句话…" data-decision-draft${state.pending?' disabled':''}>${esc(state.decisionDraft||'')}</textarea>${state.error?'<p class="error-text" role="alert">演示连接中断。输入已保留，请重试记录。</p>':''}<div class="decision-footer">${btn('稍后处理','open-goal','','back')}<span class="spacer"></span>${btn(state.error?'重试记录':'记录这个选择','decide','primary','check')}</div><div style="margin-top:16px" class="spread"><span class="small muted">仅影响本地演示数据</span><button class="small muted" data-action="simulate-error"${state.pending?' disabled':''}>体验失败与重试</button></div>`}`}</article></div>`}
function feed(){const rows=feeds.map((f,i)=>[f,i]).filter(([f])=>!state.feedSource||state.feedSource===f[1]);return `<div class="page"><div class="page-heading spread"><div><h1>${state.feedSource||'信息流'}</h1><p>先读内容，再决定它要去哪里。</p></div>${btn('来源设置','sources','','tune')}</div><div class="toolbar"><span class="small muted">${rows.length} 条内容</span><span class="spacer"></span>${btn('全部标为已读','read-all','','check')}</div>${rows.map(([f,i])=>`<section class="feed-item"><button class="feed-row" data-feed="${i}" aria-expanded="${state.feedOpen===i}">${icon(state.read.includes(i)?'rss':'dot')}<span class="feed-title">${f[0]}</span><span class="feed-source">${f[1]}</span><span class="feed-time">${f[2]}</span></button>${state.feedOpen===i?`<div class="feed-body">${f[4]?`<a class="source-link" href="${f[4]}" target="_blank" rel="noopener">查看官方原文 ${icon('external')}</a>`:'<div class="source-link muted">本地演示内容</div>'}<p>${f[3]}</p><div class="spread"><span class="small muted">已读${i===0&&state.material?' / 已存为资料':''}${i===0&&state.feedInbox?(state.feedInboxStatus==='open'?' / 已加入待决定':' / 已处理，结果保留'):''}</span><div class="flex">${i===0?btn(state.material?'查看已存资料':'存为资料',state.material?'open-shelf':'save-material','','bookmark')+btn(state.feedInbox?(state.feedInboxStatus==='open'?'查看待决定':'查看处理结果'):'加入待决定',state.feedInbox?'open-feed-inbox':'feed-inbox','secondary','inbox'):`<button class="btn" disabled title="本地内容样例；第一条提供可保存的完整路径">${icon('bookmark')}存为资料</button><button class="btn secondary" disabled title="本地内容样例；第一条提供可处理的完整路径">${icon('inbox')}加入待决定</button>`}</div></div></div>`:''}</section>`).join('')}<div class="continuity">${icon('info')}已读不等于已处理，保存资料也不会自动创建目标。</div></div>`}
function artifacts(){return `<div class="page"><div class="page-heading"><h1>成果</h1><p>看见产出，也看得见它属于哪件工作、使用了哪版依据。</p></div><div class="toolbar"><span class="small muted">本项目 / ${3+(flow.getStatus().hasResult?1:0)} 份成果</span><span class="spacer"></span>${badge('精确版本保留')}</div>${flow.resultSummary()}<div class="artifact-grid"><button class="result-card" data-action="preview"><div class="result-thumb">${preview()}</div><div class="result-meta spread"><div>首页方向稿<p>首页视觉更新 / v3</p></div>${badge('待确认','warn')}</div></button><button class="result-card" data-action="research-doc"><div class="result-thumb"><div class="doc-thumb"><h3>社区网站设计参考</h3><p>熟悉的导航，清楚的下一步。</p><div class="doc-line"></div><div class="doc-line"></div><div class="doc-line"></div><p>界面与工作流 / 观察 / 来源</p></div></div><div class="result-meta spread"><div>社区网站设计参考<p>研究目标 / v2</p></div>${badge('当前引用','good')}</div></button><button class="result-card" data-action="slides"><div class="result-thumb"><div class="slide-thumb"><small>Molis AI / 社区</small><h3 style="margin-top:12px">一起把想法<br>做成真实的事。</h3></div></div><div class="result-meta spread"><div>社区介绍提纲<p>内容目标 / v1</p></div>${badge('草稿')}</div></button></div><div class="section-head"><h2>接下来被用在哪里</h2></div><button class="recent-item" data-goal="build">${icon('link','slate')}设计参考 v2 ${icon('arrow')}首页方向稿 v3 ${icon('arrow')}首页实现<span class="spacer"></span>${icon('chevron-right')}</button></div>`}
function shelf(){return `<div class="page shelf-personal"><div class="page-heading spread"><div><div class="crumb">${icon('lock')}个人空间</div><h1>先放在这里。</h1><p>收下散落的文件，按需要处理；之后再决定用在哪件工作里。</p></div>${badge('个人置物架')}</div><div class="shelf-workbench"><div class="shelf-paper-stack" aria-hidden="true"><div class="shelf-sheet"><small>FIELD NOTES / 01</small><h3>新成员的<br>第一次参与</h3><p>从哪开始？<br>需要投入多少时间？<br>会遇见怎样的人？</p><span>访谈记录.pdf</span></div></div><section><div class="section-head"><h2>刚刚放下</h2><span class="small muted">本地文件样例</span></div><button class="shelf-row" data-action="shelf-preview">${icon('book','brown')}<span>新成员访谈记录.pdf</span><small class="muted">原件</small>${badge('未改动')}</button>${state.shelfProcessed?`<button class="shelf-row" data-action="shelf-copy">${icon('note','brown')}<span>新成员访谈记录 · 文字副本</span><small class="muted">衍生副本</small>${badge('可阅读','good')}</button>`:''}<p class="small muted" style="margin:18px 0;line-height:1.9">原件留在原处。处理产生一份副本；不会自动放进项目，也不会创建目标。</p>${btn(state.shelfProcessed?'阅读文字副本':'提取文字（样例）',state.shelfProcessed?'shelf-copy':'shelf-extract','primary','note')}<div class="shelf-scope-note">${icon('lock')}还没有选用到任何项目</div></section></div><div class="section-head"><h2>项目里已选用的材料</h2></div><p class="soft">信息流收下的观察留在当前项目，和这里的个人文件分开。</p><button class="recent-item" data-page="materials">${icon('rss','brown')}网站更新 / 项目资料<span class="spacer"></span>${icon('chevron-right')}</button><div class="continuity">当前可体验固定样例的原件与副本关系；文件拖入、本机抽字未接通。</div></div>`}
function materials(){return `<div class="page"><div class="page-heading"><div class="crumb"><button data-page="feed">信息流</button>${icon('chevron-right')}网站更新</div><h1>项目资料</h1><p>正式选进这件工作的材料，保留来源与引用版本。</p></div><div class="toolbar"><span class="small muted">${state.material?'2':'1'} 份参考</span><span class="spacer"></span>${btn('回到信息流','open-feed','','back')}</div><button class="shelf-row" data-action="research-doc">${icon('book','brown')}<span>社区网站设计参考</span><small class="muted">当前引用</small>${badge('v2')}</button>${state.material?`<button class="shelf-row" data-action="saved-material">${icon('bookmark','brown')}<span>界面的上下文，应该让人看得见</span><small class="muted">信息流原文</small>${badge('已保存','good')}</button>`:''}<div class="notice">保存材料只保留参考。它何时成为目标的依据，由具体工作决定。</div></div>`}
function sessions(){return `<div class="page"><div class="page-heading spread"><div><h1>把工作交代清楚，再继续。</h1><p>当前目标、这轮输入和未完成事项，跟着工作走。</p></div>${badge('示例会话')}</div><div class="context-strip">${icon('link')}此会话关联<button class="context-chip" data-goal="design">首页视觉更新</button><button class="context-chip" data-action="research-doc">设计参考 v2</button><button class="context-chip" data-action="agreement">目标约定 v2</button></div><div class="session-shell"><div class="session-top">${icon('terminal','purple')}Codex / 首页实现<span class="spacer"></span>${badge('可查看')}</div><div class="session-content"><span class="small muted">上次留下的工作摘要 / 示例</span><div class="session-message">导航结构已整理。<br>${state.accepted?'首轮范围已记录：'+esc(choiceLabel())+'。下一步据此继续实现。':'下一步先确认首轮内容范围，再实现首页与社区入口。'}<br>还需要用实际手机走完加入路径。</div><pre>当前目录  /molis-ai/website<br>引用输入  设计参考 v2 · 首页方向稿 v3<br>尚未验证  移动端加入路径</pre><p class="small muted">当前为会话接续界面样张，没有执行终端或调用 Agent。</p></div></div>${flow.goalNotice()}<div class="section-head"><h2>在别的工具继续</h2></div><p class="small muted">先预览会携带的上下文，再由你决定使用哪个执行入口。</p><div style="margin-top:15px">${btn('预览接续内容','handoff','primary','arrow')}</div></div>`}
function schedule(){return `<div class="page"><div class="page-heading"><h1>日程</h1><p>时间安排与目标状态分开。到点提醒，不等于工作已经完成。</p></div><div class="section-head"><h2>9 月 21 日，周一</h2>${badge('示例安排')}</div>${[['10:00','确认首页方向','关联：首页视觉更新','scope-decision','待确认'],['14:30','阅读本周设计观察','来源：信息流','open-feed','可查看'],['16:00','核对跨工具接续内容','关联：首页实现','handoff','准备中']].map(x=>`<div class="schedule-row"><time>${x[0]}</time><div>${x[1]}<p>${x[2]}</p></div>${btn(x[4],x[3],'secondary')}</div>`).join('')}<div class="notice">这些时间仅用于布局演示，未创建真实提醒或自动执行任务。</div></div>`}
function functionsPage(){return `<div class="page"><div class="page-heading"><h1>函数</h1><p>把重复的判断写清楚，在使用它的地方生效。</p></div><div class="spread"><h2 style="font-size:15px">设计观察内容筛选</h2>${badge('演示配置')}</div><div class="functions-flow"><div class="function-step">${icon('rss')}<h3>接收来源内容</h3><p>设计观察 / 信息流</p></div>${icon('arrow')}<div class="function-step">${icon('filter')}<h3>判断是否相关</h3><p>导航、阅读、人与 AI 协作</p></div>${icon('arrow')}<div class="function-step">${icon('inbox')}<h3>交给人判断</h3><p>保留理由和原文入口</p></div></div><div class="readout">判断规则<p>当内容包含可验证的产品交互案例时，说明与网站更新的关系；无法判断时保留原文，不自动转成正式目标。</p></div>${btn('用样例试跑','try-function','primary','play')}<div class="section-head"><h2>被用在哪里</h2></div><button class="recent-item" data-page="feed">${icon('rss','brown')}设计观察来源<span class="spacer"></span>在来源现场配置 ${icon('chevron-right')}</button></div>`}
function apps(){return `<div class="page"><div class="page-heading"><h1>为工作选择合适的应用。</h1><p>应用有自己的工作面，目标、输入和成果保持可追溯。</p></div><div class="app-grid">${[['note','Pages','文稿、研究笔记与评论','brown','writing-doc'],['code','Coding','带着目标继续代码工作','cyan','open-sessions'],['database','Dataset','从记录到可复用的数据','blue','dataset'],['image','PPT','把结论整理为演示提纲','purple','slides'],['review','Forms','收集结构化的真实反馈','green','form'],['idea','灵光','先把还没想清楚的念头留下','amber','idea']].map(x=>`<button class="app-row" style="--tint:var(--${x[3]})" data-action="${x[4]}"><span class="app-icon">${icon(x[0])}</span><div>${x[1]}<p>${x[2]}</p></div>${icon('chevron-right')}</button>`).join('')}</div><div class="continuity">${icon('info')}Pages 可编辑、交回本地版本并逐段审阅；其余入口展示设计安排。</div></div>`}
function settings(){return `<div class="page settings-page"><div class="page-heading"><h1>外观与阅读</h1><p>当前设置仅影响这份设计样例。</p></div><div class="setting-row"><div>外观<p>浅深色共用相同的层级和状态含义。</p></div><div class="segmented"><button data-theme="light" class="${state.theme==='light'?'active':''}">浅色</button><button data-theme="dark" class="${state.theme==='dark'?'active':''}">深色</button></div></div><div class="setting-row"><div>默认工作布局<p>比较找回工作与对照结果两种阅读次序。</p></div><div class="segmented"><button data-mode="continuum" class="${state.mode==='continuum'?'active':''}">续流</button><button data-mode="atlas" class="${state.mode==='atlas'?'active':''}">对照台</button></div></div><div class="setting-row"><div>回到目标时只看当前事项<p>在目标页收起历史记录，只保留本轮结果与缺口。</p></div><button role="switch" class="switch" aria-label="只看当前事项" aria-checked="${state.onlyFocus}" data-action="focus-only"></button></div><div class="setting-row"><div>减少动态效果<p>自动遵循系统的减少动态效果设置。</p></div>${badge('跟随系统')}</div><div class="setting-row"><div>重置本地演示数据<p>清除这份样例的备注、选择与资料，恢复初始内容。</p></div>${btn('重置样例','reset','secondary')}</div><div style="margin-top:25px">${btn('回到工作','open-goal','','back')}</div></div>`}
function render(){captureScroll();document.title=`Molis Work · ${state.mode==='atlas'?'B 对照台':'A 续流'} · ${pages[state.page]}`;document.documentElement.dataset.theme=state.theme;$('#app').innerHTML=`${header()}<div class="shell" data-direction="${state.mode}"><header class="titlebar">${ib('sidebar','打开导航','mobile-nav')}<div class="brand"><span class="brandmark" aria-hidden="true"><i></i><i></i><i></i></span>molis work</div><button class="project-name flex" data-action="${state.page==='shelf'?'shelf-space':'project'}">${state.page==='shelf'?'我的个人空间':'Molis AI 网站更新'} ${icon('chevron-down')}</button><span class="spacer"></span><span class="local-indicator"><span></span>本地样例</span><button class="btn small" data-action="search" aria-label="搜索全部工作">${icon('search')}<span>搜索</span><kbd>⌘ K</kbd></button><span class="avatar">O</span></header>${rail()}${sidebar()}<main class="stage">${tabs()}<div class="content" id="content">${({home,goals:goalsPage,goal,inbox,feed,artifacts,shelf,materials,sessions,schedule,functions:functionsPage,apps,settings,...flow.pages}[state.page]||home)()}</div></main></div>`;$('.titlebar>.icon-btn').classList.add('mobile-menu');if(state.onlyFocus&&state.page==='goal')document.querySelectorAll('.event').forEach(el=>el.hidden=true);renderedPageKey=pageKey();const content=$('#content');content.scrollTop=state.scrollPositions[renderedPageKey]||0;}
function go(page){if(!pages[page])return;captureScroll();if(['change','writing','workreview'].includes(page))state.goalId='design';state.page=page;location.hash=page==='goal'?'goal/'+encodeURIComponent(state.goalId):page==='inbox'?'inbox/'+state.inboxId:page;render()}
function openGoal(id='design'){captureScroll();state.goalId=[...goals,...state.created].some(g=>g.id===id)?id:'design';go('goal')}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200)}
let restoreFocus;
function openDialog(title,body,footer=''){restoreFocus=document.activeElement;const d=$('#dialog');d.innerHTML=`<div class="dialog-header"><h2>${title}</h2>${ib('x','关闭','close')}</div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;if(!d.open)d.showModal();}
function closeDialog(){const d=$('#dialog');if(d.open)d.close();if(restoreFocus?.isConnected)restoreFocus.focus();}
$('#dialog').addEventListener('close',()=>{if(restoreFocus?.isConnected)restoreFocus.focus()});
const actions={
 'shelf-space':()=>openDialog('我的个人空间',`<p>置物架中的原件与副本留在个人空间。当前示例没有把它们加入项目、创建目标或分享给他人。</p>`,btn('关闭','close')),
 'shelf-preview':()=>openDialog('新成员访谈记录.pdf / 原件样例',`<p>一份访谈笔记的文件样例，用于展示个人材料如何被放下和处理。</p><div class="readout">受访者关心：第一次可以做什么、需要多少时间、是否需要先读完整的社区介绍。</div><p>未选择项目。原件未改变。</p>`,btn('关闭','close')+btn('提取文字（样例）','shelf-extract','primary','note')),
 'shelf-extract':()=>{state.shelfProcessed=true;persist();closeDialog();render();toast('已生成本地样例文字副本；原件保持不变')},
 'shelf-copy':()=>openDialog('文字副本 / 个人材料',`<div class="readout">新成员的第一次参与<p>我想知道第一次能做什么、要花多久，以及是否可以先来一次活动。相比先读完全部介绍，我更希望有一个具体的开始。</p></div><p>来源：新成员访谈记录.pdf。此处使用固定样例文字，没有执行真实抽字或进入项目。</p>`,btn('关闭','close')),

 'open-goal':()=>openGoal(), 'open-sessions':()=>go('sessions'),'open-feed':()=>go('feed'),'open-shelf':()=>go('materials'),'open-inbox':()=>go('inbox'),close:closeDialog,
 theme:()=>{state.theme=state.theme==='light'?'dark':'light';persist();render()},
 project:()=>openDialog('当前项目',`<div class="readout">Molis AI 网站更新<p class="small muted">这是用来比较界面的固定样例项目，不会连接、切换或覆盖你的真实项目。</p></div>${btn('回到继续工作','project-home','secondary','home')}`),
 'project-home':()=>{closeDialog();go('home')},
 guide:()=>openDialog('从一条新反馈，走到下一版成果',`<p>先看首页的变化提示，进入「核对这次变化」。对照现行要求与新反馈，采用或留到下一轮。</p><p>采用后继续编辑加入指引。草稿自动留在本地；「交回这一版」产生一个可单独审阅的成果版本。</p><p>在对照面点选段落、记录返工意见，再回到原文修订。第二次交回会保留第一版与它的意见。</p><p>A / B 比较导航布局；同一份工作可以随时切换。⌘/Ctrl K 搜索，Esc 关闭浮层。</p><div class="notice">全部为本地样例。可体验状态流转；未连接生产 Pages、Agent 或团队空间。</div>`,btn('从首页开始','start-guide','primary')),
 'start-guide':()=>{closeDialog();go('home')},
 reset:()=>openDialog('重置这份样例',`<p>只会重置此浏览器里的演示备注、决定、目标和资料。你的仓库和 Molis Work 数据不受影响。</p>`,btn('取消','close')+btn('重置样例','confirm-reset','primary')),
 'confirm-reset':()=>{flow.reset();clearTimeout(decisionTimer);closeDialog();Object.assign(state,{accepted:false,choice:'narrow',note:'',notes:[],read:[],material:false,shelfProcessed:false,feedInbox:false,feedInboxStatus:'open',feedInboxReceipt:null,inboxId:'scope',created:[],error:false,pending:false,decisionDraft:'',decisionRecord:null,onlyFocus:false,goalId:'design',feedOpen:null,feedSource:null,query:'',filter:'all',listMode:'list',scrollPositions:{}});renderedPageKey=null;persist();go('home');toast('本地样例已重置')},
 'scope-decision':()=>{state.inboxId='scope';go('inbox')},'review-decision':()=>{state.inboxId='review';go('inbox')},
 'simulate-error':()=>{if(state.pending)return;state.error=true;persist();render()},
 decide:()=>{if(state.pending||state.accepted)return;const submitted={choice:state.choice,note:state.decisionDraft.trim(),at:new Date().toISOString()};state.pending=true;render();decisionTimer=setTimeout(()=>{state.accepted=true;state.choice=submitted.choice;state.decisionRecord=submitted;state.pending=false;state.error=false;persist();render();toast('选择已记录到本地样例；目标仍待验收')},450)},
 'save-note':()=>{const text=state.note.trim();if(!text){toast('先写下一句进展或问题');$('[data-draft]')?.focus();return}state.notes.unshift(text);state.note='';persist();render();toast('备注已保留在本地样例')},
 preview:()=>openDialog('首页方向稿 / v3',`${preview()}<div class="context-strip">${icon('link')}使用：设计参考 v2 ${icon('arrow')}产出：方向稿 v3</div><p>这是用来比较工作界面的示例成果。页面内的绿色网站设计是内容预览，不是 Molis Work 的第二套皮肤。</p><p>目前仍缺真实手机上的加入路径验证。</p>`,btn('关闭','close')+btn('回到关联目标','dialog-goal','primary','target')),
 'dialog-goal':()=>{closeDialog();openGoal()},
 agreement:()=>openDialog('当前约定 / v2',`<p>预期结果：让第一次访问的人看懂社区在做什么，并找到适合自己的参与方式。</p><div class="readout">保留内容范围<p>产品、解决方案、观点、社区、Molis Wikipedia。</p></div><p>完成依据：内容入口可达；加入路径可理解；在手机上走完主要流程。设计稿出现入口，只能证明设计意图。</p><p class="muted">本轮样例不会改写真实 Goal 约定。</p>`,btn('关闭','close')),
 'research-doc':()=>openDialog('社区网站设计参考 / v2',`<p>把工作入口与资料放在用户能连续浏览的区域，减少反复返回首页。</p><div class="readout">从竞品中吸收的三种机制<p>Linear：列表快速扫读与就地预览。<br>Taskade：把当前上下文放在输入现场。<br>Multica：执行结束后进入结果复核。</p></div><p>这是原型中的样例摘要。完整研究与来源位于同目录的 research-platforms.md 和 research-workflows.md。</p><p class="small muted">引用此版本：网站首页视觉更新 → 首页方向稿 v3。</p>`,btn('关闭','close')+btn('查看使用此资料的目标','dialog-goal','secondary')),
 history:()=>openDialog('工作历史',`${notes()}<div class="event"><span class="event-mark">${icon('target','blue')}</span><div>目标约定更新为 v2<p>保留五类内容，补充手机上的加入路径。</p></div></div>`,btn('关闭','close')),
 create:()=>openDialog('新建目标',`<label class="small muted" for="goal-name">想完成什么？</label><input class="field plain-input" id="goal-name" placeholder="给这件事起一个名字" maxlength="100" value="${esc(state.createName||'')}"><label for="goal-outcome">希望得到什么结果？</label><textarea class="field" id="goal-outcome" placeholder="例如，让新成员能独立完成第一次参与…">${esc(state.createOutcome||'')}</textarea><p class="small muted" style="margin:13px 0 0">仅创建本地示例目标，不启动任何执行。</p>`,btn('取消','close')+btn('创建目标','confirm-create','primary','plus')),
 'confirm-create':()=>{const name=$('#goal-name').value.trim(),outcome=$('#goal-outcome').value.trim();if(!name){$('#goal-name').focus();toast('给这件事起一个名字');return}const id='sample-'+Date.now();state.created.push({id,title:name,outcome,status:'可继续',kind:'progress',type:'新目标',detail:'目标已保留，下一步明确当前要求。'});state.createName='';state.createOutcome='';persist();closeDialog();openGoal(id);toast('本地示例目标已创建')},
 'filter-attention':()=>{state.filter=state.filter==='attention'?'all':'attention';render()},'clear-filter':()=>{state.query='';state.filter='all';render()},
 'save-material':()=>{if(state.feedOpen===0){state.material=true;persist();render();toast('已存为资料，保留原文来源')}else openDialog('保存资料',`<p>这条内容属于虚构的本地样例。为了体验可恢复的完整路径，请保存第一条「界面的上下文，应该让人看得见」。</p>`,btn('查看第一条','first-feed','primary'))},
 'first-feed':()=>{closeDialog();state.feedSource=null;state.page='feed';state.feedOpen=0;state.read=[...new Set([...state.read,0])];persist();go('feed')},
 'feed-inbox':()=>{if(state.feedOpen!==0){actions['save-material']();return}state.feedInbox=true;state.feedInboxStatus='open';state.feedInboxReceipt=null;persist();render();toast('已加入待决定；没有自动创建目标')},
 'open-feed-inbox':()=>{captureScroll();state.inboxId='feed';go('inbox')},
 'feed-keep':()=>{state.material=true;state.feedInboxStatus='done';state.feedInboxReceipt={text:'已存为资料并标记处理，保留原文来源；没有创建目标。',at:new Date().toISOString()};persist();render();toast('资料与处理结果已保留')},
 'feed-done':()=>{state.feedInboxStatus='done';state.feedInboxReceipt={text:'已标记处理，原文保留；没有改变目标或创建新事项。',at:new Date().toISOString()};persist();render();toast('处理结果已保留')},
 'feed-reopen':()=>{state.feedInboxStatus='open';persist();render();toast('已重新打开此项')},
 'saved-material':()=>openDialog('来自信息流的资料',`<p>${feeds[0][3]}</p><a class="btn secondary" href="${feeds[0][4]}" target="_blank" rel="noopener">查看官方来源 ${icon('external')}</a><div class="readout">保存状态：已存为资料。<p>阅读状态和保存去向分别保留，原始来源可回溯。</p></div>`,btn('关闭','close')),
 'read-all':()=>{state.read=[0,1,2,3];persist();render();toast('4 条内容已标为已读；处理去向保持原样')},'all-feeds':()=>{state.feedSource=null;go('feed')},
 sources:()=>openDialog('来源现场配置',`<div class="readout">设计观察<p>内容类型：官方产品与交互资料。<br>收集方式：手工整理（本地样例）。</p></div><p>正式方案在来源任务里配置同步、授权和规则；连接中断在这里修复，已读与原文仍然保留。</p><p class="small muted">当前 Demo 未连接来源账号，没有同步开关。</p>`,btn('关闭','close')),
 handoff:()=>openDialog('接续前，先看携带什么',`<div class="context-strip"><span class="context-chip">目标约定 v2</span><span class="context-chip">设计参考 v2</span><span class="context-chip">方向稿 v3</span></div><div class="readout">要继续的工作<p>实现网站首页与社区入口。${state.accepted?'页面范围决定已记录。':'先确认首轮范围。'}<br>不能跳过的检查：手机上的真实加入路径。</p></div><p>不携带私人草稿、其他项目或完整历史聊天。</p><p class="small muted">正式产品应在这里预览、确认，再交给选中的 Runtime。本演示只展示文本，不启动或发送。</p>`,btn('关闭','close')+btn('复制接续摘要','copy-handoff','primary','copy')),
 'copy-handoff':async()=>{const summary=`本地设计样例：网站首页视觉更新。引用目标约定 v2、设计参考 v2、方向稿 v3。${state.accepted?'页面范围决定：'+choiceLabel()+'。下一步按此范围实现。':'下一步核对首轮范围并实现首页。'}仍需实际手机加入路径验收。`;try{await navigator.clipboard.writeText(summary);toast('样例摘要已复制，没有发送给 Agent')}catch{toast('浏览器未允许复制，可直接选取窗口里的文字')}},
 'writing-doc':()=>go('writing'),
 'flow-open-writing':()=>go('writing'),'flow-open-review':()=>go('workreview'),
 slides:()=>openDialog('PPT / 社区介绍提纲',`<div class="slide-thumb" style="height:190px"><small>Molis AI</small><h3>一起把想法<br>做成真实的事。</h3></div><p style="margin-top:16px">设计安排：左侧页面缩略图，中间演示面，右侧当前页属性；引用的研究与目标在工具栏查看。导出类型必须写明，不把 JSON 导出称为 PPTX。</p>`,btn('关闭','close')),
 dataset:()=>openDialog('Dataset / 数据工作面',`<div class="readout">字段、记录与使用它的工作<p>主体保持可编辑数据表。列定义现场修改，导入先给预览；保存版本后，引用它的成果明确使用哪个版本。</p></div><p>本轮只展示界面安排，未接入真实数据表操作。</p>`,btn('关闭','close')),
 form:()=>openDialog('Forms / 反馈工作面',`<p>设计、填写预览与结果三种明确视图。结果页先展示原始答复，再给统计与来源；AI 生成题目未接通时不能显示为已生成。</p><div class="readout">样例问题：第一次访问后，你知道如何参与吗？<p>明确知道 / 大概知道 / 还不清楚</p></div>`,btn('关闭','close')),
 idea:()=>openDialog('灵光 / 先留住念头',`<p>轻量书写和最近记录，减少整理压力。转为目标应另行确认，记录灵感不自动作出工作承诺。</p><textarea class="field" aria-label="灵感草稿" data-idea placeholder="忽然想到的一件事…">${esc(state.idea||'')}</textarea>`,btn('关闭','close')+btn('保留本页草稿','save-idea','primary')),
 'save-idea':()=>{closeDialog();toast('草稿保留在当前页面，未变成目标')},
 'try-function':()=>openDialog('样例试跑结果',`<div class="readout">匹配：界面的上下文，应该让人看得见<p>原因：内容包含上下文呈现机制，与跨工具继续工作有关。</p></div><p>建议去向：待你决定。这里展示固定试跑样例，未调用模型、未创建事项。</p>`,btn('关闭','close')+btn('查看输入内容','first-feed','secondary')),
 'focus-only':()=>{state.onlyFocus=!state.onlyFocus;persist();render()},'context-help':()=>actions.guide(),
 'mobile-nav':()=>openDialog('打开工作面',`<div class="nav-drawer-list">${[...nav,['settings','settings','偏好设置','slate']].map(n=>`<button data-dialog-page="${n[0]}" class="flex">${icon(n[1],n[3])}${n[2]}</button>`).join('')}</div>`),
 search:()=>{restoreFocus=document.activeElement;const d=$('#dialog');d.innerHTML=`<input class="command-input" aria-label="搜索全部工作" placeholder="找目标、资料或工作面…" id="command-search"><div class="dialog-body" id="command-results">${commandResults('')}</div><div class="dialog-footer"><span class="keyboard-hint">Tab 选择 / Enter 打开 / Esc 返回</span></div>`;if(!d.open)d.showModal();$('#command-search').focus()}
};
function commandResults(q){const results=[...Object.entries(pages).filter(([p])=>p!=='goal').map(([p,t])=>({t,p})),...[...goals,...state.created].map(g=>({t:g.title,g:g.id}))].filter(x=>x.t.toLowerCase().includes(q.toLowerCase()));return results.length?results.map(x=>`<button class="command-item" ${x.g?`data-command-goal="${x.g}"`:`data-command-page="${x.p}"`}>${icon(x.g?'target':'arrow')}${esc(x.t)}<span class="spacer"></span><small class="muted">${x.g?'目标':'工作面'}</small></button>`).join(''):'<p class="muted">没有匹配结果。试试“目标”或“资料”。</p>'}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.action){actions[b.dataset.action]?.();return}if(b.dataset.dialogPage){closeDialog();go(b.dataset.dialogPage);return}if(b.dataset.commandPage){closeDialog();go(b.dataset.commandPage);return}if(b.dataset.commandGoal){closeDialog();openGoal(b.dataset.commandGoal);return}if(b.dataset.page){go(b.dataset.page);return}if(b.dataset.goal){openGoal(b.dataset.goal);return}if(b.dataset.mode){state.mode=b.dataset.mode;const url=new URL(location);url.searchParams.set('direction',state.mode);history.replaceState(null,'',url);render();return}if(b.dataset.theme){state.theme=b.dataset.theme;persist();render();return}if(b.dataset.decision){state.inboxId=b.dataset.decision;go('inbox');return}if(b.dataset.choice){if(state.pending||state.accepted)return;state.choice=b.dataset.choice;persist();render();return}if(b.dataset.feed){const i=Number(b.dataset.feed);state.feedOpen=state.feedOpen===i?null:i;state.read=[...new Set([...state.read,i])];persist();render();return}if(b.dataset.source){state.feedSource=b.dataset.source;state.feedOpen=null;go('feed');return}if(b.dataset.listmode){state.listMode=b.dataset.listmode;render()}});
document.addEventListener('input',e=>{flow.onInput(e);if(e.target.matches('[data-draft]')){state.note=e.target.value;persist()}if(e.target.matches('[data-decision-draft]')){state.decisionDraft=e.target.value;persist()}if(e.target.id==='goal-name')state.createName=e.target.value;if(e.target.id==='goal-outcome')state.createOutcome=e.target.value;if(e.target.matches('[data-idea]'))state.idea=e.target.value;if(e.target.id==='command-search')$('#command-results').innerHTML=commandResults(e.target.value);if(e.target.matches('[data-search-goals]')){state.query=e.target.value;const pos=e.target.selectionStart;render();const input=$('[data-search-goals]');input.focus();input.setSelectionRange(pos,pos)}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();actions.search()}if((e.metaKey||e.ctrlKey)&&e.key==='Enter'){if($('#dialog').open&&$('#goal-name')){e.preventDefault();actions['confirm-create']()}else if(e.target.matches('[data-draft]')){e.preventDefault();actions['save-note']()}}});
window.addEventListener('hashchange',()=>{const route=readRoute();const id=[...goals,...state.created].some(g=>g.id===route.goalId)?route.goalId:'design';if(state.page!==route.page||(route.page==='goal'&&state.goalId!==id)||(route.page==='inbox'&&state.inboxId!==route.inboxId)){captureScroll();state.page=route.page;if(route.page==='goal')state.goalId=id;else if(['change','writing','workreview'].includes(route.page))state.goalId='design';if(route.page==='inbox')state.inboxId=route.inboxId;render()}});
window.addEventListener('pagehide',persist);
if(![...goals,...state.created].some(g=>g.id===state.goalId))state.goalId='design';
flow=createFlow({icon,esc,btn,badge,go,toast,openDialog,closeDialog,render});
Object.assign(actions,flow.actions);
render();
